44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        Collection<Owner> existingOwners = this.clinicService.findAllOwners();
105	        boolean telephoneTaken = existingOwners.stream()
106	            .anyMatch(existing -> existing.getTelephone().equals(owner.getTelephone()));
107	        if (telephoneTaken) {
108	            return new ResponseEntity<>(HttpStatus.CONFLICT);
109	        }
110	        String last = owner.getLastName();
111	        owner.setCustomerCode(last.substring(0, Math.min(3, last.length())).toUpperCase()
112	            + String.format("-%04d", existingOwners.size() + 1));
113	        this.clinicService.saveOwner(owner);
114	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
115	        headers.setLocation(UriComponentsBuilder.newInstance()
116	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
117	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
123	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
124	        if (currentOwner == null) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        currentOwner.setAddress(ownerFieldsDto.getAddress());
128	        currentOwner.setCity(ownerFieldsDto.getCity());
129	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
130	        currentOwner.setLastName(ownerFieldsDto.getLastName());
131	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
132	        this.clinicService.saveOwner(currentOwner);
133	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Transactional
138	    @Override
139	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
140	        Owner owner = this.clinicService.findOwnerById(ownerId);
141	        if (owner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        this.clinicService.deleteOwner(owner);
145	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        HttpHeaders headers = new HttpHeaders();
156	        Pet pet = petMapper.toPet(petFieldsDto);
157	        owner.setId(ownerId);
158	        pet.setOwner(owner);
159	        pet.getType().setName(null);
160	        this.clinicService.savePet(pet);
161	        PetDto petDto = petMapper.toPetDto(pet);
162	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
163	            .buildAndExpand(pet.getId()).toUri());
164	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
170	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
171	        if (currentOwner != null) {
172	            Pet currentPet = this.clinicService.findPetById(petId);
173	            if (currentPet != null) {
174	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
175	                currentPet.setName(petFieldsDto.getName());
176	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
177	                this.clinicService.savePet(currentPet);
178	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
179	            }
180	        }
181	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
187	        HttpHeaders headers = new HttpHeaders();
188	        Visit visit = visitMapper.toVisit(visitFieldsDto);
189	        Pet pet = new Pet();
190	        pet.setId(petId);
191	        visit.setPet(pet);
192	        this.clinicService.saveVisit(visit);
193	        VisitDto visitDto = visitMapper.toVisitDto(visit);
194	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
195	            .buildAndExpand(visit.getId()).toUri());
196	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
197	    }
